# UCS CatIDs that are deliberately not projected into the 22 categories.
# Two reasons: entries with no home here (archive housekeeping,
# compressed air, chemistry, process words), and entries whose CatID the
# corpus measurement contradicts. The classifier must not treat either as a
# declared category. The value is the reason, carried from
# `ucs_mapping.DROPPED` / `WITHHELD_CAT_IDS` so the lists cannot drift.
